/**
 * Typed client for the SwapDesk local mock API.
 *
 * The browser calls same-origin `/v1/...` paths; `next.config.ts` proxies
 * those to the FastAPI backend (default `http://127.0.0.1:8000`). Set
 * `NEXT_PUBLIC_SWAPDESK_API_URL` to call a remote origin directly instead
 * (that origin must then allow CORS).
 */

const API_ORIGIN = (process.env.NEXT_PUBLIC_SWAPDESK_API_URL ?? "").replace(/\/$/, "");

export const API_BASE = `${API_ORIGIN}/v1`;

export class ApiError extends Error {
  status: number;
  detail: unknown;

  constructor(status: number, message: string, detail?: unknown) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.detail = detail;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${API_BASE}${path}`, {
      ...init,
      headers: {
        ...(init?.body ? { "Content-Type": "application/json" } : {}),
        ...init?.headers,
      },
      cache: "no-store",
    });
  } catch {
    throw new ApiError(0, "Cannot reach the SwapDesk API. Is the backend running?");
  }

  const text = await response.text();
  const payload = text ? safeJson(text) : null;

  if (!response.ok) {
    const detail =
      payload && typeof payload === "object" && "detail" in payload
        ? (payload as { detail: unknown }).detail
        : payload;
    const message =
      typeof detail === "string" ? detail : `Request failed with status ${response.status}`;
    throw new ApiError(response.status, message, payload);
  }

  return payload as T;
}

function safeJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

/* ------------------------------------------------------------------ types */

export type Outcome = "arranged" | "clarification" | "denial" | "escalation";

export type HealthOut = {
  ok: boolean;
  service: string;
};

export type ReturnPolicy = {
  window_days: number;
  eligible_status: string;
  final_sale_excluded: boolean;
};

export type FixtureItem = {
  id: string;
  sku: string;
  size: string;
  qty: number;
  status: string;
  delivered_at: string | null;
  final_sale: boolean;
};

export type FixtureOrder = {
  id: string;
  customer_ref: string;
  items: FixtureItem[];
};

export type FixturesOut = {
  orders: FixtureOrder[];
  policy: ReturnPolicy;
};

export type TicketIn = {
  order_id: string;
  order_item_id: string;
  size?: string;
  qty?: number;
  message?: string;
  consent_size?: string | null;
  case_id?: string | null;
};

export type TicketOut = {
  case_id: string;
  run_id: string;
  outcome: Outcome;
  reply: string;
  exchange_id: string | null;
  attempts: Record<string, number>;
};

export type AgentTicketIn = {
  message: string;
  order_id?: string | null;
  order_item_id?: string | null;
  size?: string | null;
  qty?: number;
  consent_size?: string | null;
  case_id?: string | null;
  resume?: boolean;
};

export type AgentTicketOut = {
  case_id: string;
  run_id: string;
  outcome: Outcome;
  reply: string;
  exchange_id: string | null;
  resumed: boolean;
};

export type CaseStatusOut = {
  case_id: string;
  outcome: Outcome;
  reply: string;
  exchange_id: string | null;
  runs: string[];
};

export type TimelineEvent = {
  op_key: string;
  op_type: string | null;
  event: string;
  status: string | null;
  result: Record<string, unknown> | null;
  created_at: string;
};

export type ContinueIn = {
  message?: string;
  consent_size?: string | null;
  order_id?: string | null;
  order_item_id?: string | null;
  size?: string | null;
  qty?: number;
};

export type ContinueOut = {
  case_id: string;
  run_id: string | null;
  outcome: Outcome;
  reply: string;
  exchange_id: string | null;
  attempts: Record<string, number>;
  continued: boolean;
};

export type FaultIn = {
  case_id: string;
  run_id?: string;
  step: string;
  point: string;
  times?: number;
};

export type FaultOut = {
  armed: boolean;
  op_key: string;
  point: string;
  times: number;
};

/* -------------------------------------------------------------- endpoints */

/** GET /v1/health — liveness probe. */
export function getHealth(): Promise<HealthOut> {
  return request<HealthOut>("/health");
}

/** GET /v1/fixtures — synthetic orders/items and the return policy. */
export function getFixtures(): Promise<FixturesOut> {
  return request<FixturesOut>("/fixtures");
}

/** POST /v1/tickets — deterministic ticket run to a verified outcome. */
export function submitTicket(input: TicketIn): Promise<TicketOut> {
  return request<TicketOut>("/tickets", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

/** POST /v1/agent/tickets — natural-language run through the LangGraph agent. */
export function submitAgentTicket(input: AgentTicketIn): Promise<AgentTicketOut> {
  return request<AgentTicketOut>("/agent/tickets", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

/** GET /v1/cases/{id} — verified status of a case. */
export function getCase(caseId: string): Promise<CaseStatusOut> {
  return request<CaseStatusOut>(`/cases/${encodeURIComponent(caseId)}`);
}

/** GET /v1/cases/{id}/timeline — sanitized action/journal events. */
export function getCaseTimeline(caseId: string): Promise<TimelineEvent[]> {
  return request<TimelineEvent[]>(`/cases/${encodeURIComponent(caseId)}/timeline`);
}

/** POST /v1/cases/{id}/continue — continue a case with new input/consent. */
export function continueCase(caseId: string, input: ContinueIn): Promise<ContinueOut> {
  return request<ContinueOut>(`/cases/${encodeURIComponent(caseId)}/continue`, {
    method: "POST",
    body: JSON.stringify(input),
  });
}

/** POST /v1/demo/faults — arm a demo-only failure on an operation key. */
export function armFault(input: FaultIn): Promise<FaultOut> {
  return request<FaultOut>("/demo/faults", {
    method: "POST",
    body: JSON.stringify(input),
  });
}

/** DELETE /v1/demo/faults — disarm every armed failure. */
export function clearFaults(): Promise<{ cleared: boolean }> {
  return request<{ cleared: boolean }>("/demo/faults", { method: "DELETE" });
}

