"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  armFault as apiArmFault,
  clearFaults as apiClearFaults,
  continueCase as apiContinueCase,
  getCaseTimeline,
  getCase as apiGetCase,
  getFixtures as apiGetFixtures,
  getHealth as apiGetHealth,
  submitAgentTicket as apiSubmitAgentTicket,
  submitTicket as apiSubmitTicket,
  type AgentTicketIn,
  type CaseStatusOut,
  type ContinueIn,
  type ContinueOut,
  type FaultIn,
  type FaultOut,
  type FixturesOut,
  type Outcome,
  type TicketIn,
  type TimelineEvent,
} from "@/lib/api";

export type TicketStatus = "resolved" | "escalated" | "processing";

export type Ticket = {
  id: string;
  message: string;
  status: TicketStatus;
  statusLabel: string;
  actions: string[];
  time: string;
  sku: string;
  /** Set for cases created through the backend API. */
  outcome?: Outcome;
  reply?: string;
  exchangeId?: string | null;
  runId?: string;
  live?: boolean;
};

export type InventoryItem = {
  sku: string;
  name: string;
  size: number;
  stock: number;
  res: number;
  wh: string;
};

export type ApiHealth = "unknown" | "online" | "offline";

export const MOCK_TICKET = {
  message: "Jordan 4 size 43 exchange",
  status: "resolved" as TicketStatus,
  statusLabel: "Resolved Autonomously",
  actions: ["RESERVE_STOCK", "CREATE_LABEL"],
  time: "Just now",
  sku: "AJ4-MIL-43",
};

const createInitialTickets = (): Ticket[] => [
  {
    id: "TCK-9042",
    message: "Jordan 4s are too tight, need size 43.",
    status: "resolved",
    statusLabel: "Resolved Autonomously",
    actions: ["RESERVE_STOCK", "CREATE_LABEL"],
    time: "Just now",
    sku: "AJ4-MIL-43",
  },
  {
    id: "TCK-9043",
    message: "I want a refund but I bought these 90 days ago.",
    status: "escalated",
    statusLabel: "Escalated to Human",
    actions: ["POLICY_DENY"],
    time: "2 min ago",
    sku: "SMB-OG-41",
  },
  {
    id: "TCK-9044",
    message: "Need a size 10 exchange.",
    status: "resolved",
    statusLabel: "Resolved (Recovered)",
    actions: ["API_TIMEOUT_RECOVERED"],
    time: "5 min ago",
    sku: "GK30-BLK-44",
  },
];

const createInitialInventory = (): InventoryItem[] => [
  { sku: "AJ4-MIL-43", name: "Air Jordan 4 Military", size: 43, stock: 5, res: 1, wh: "WH-AMS-02" },
  { sku: "AJ4-MIL-42", name: "Air Jordan 4 Military", size: 42, stock: 3, res: 0, wh: "WH-AMS-02" },
  { sku: "SMB-OG-41", name: "Adidas Samba OG", size: 41, stock: 12, res: 2, wh: "WH-BER-01" },
  { sku: "NB550-GRY-39", name: "New Balance 550 Grey", size: 39, stock: 0, res: 0, wh: "WH-BER-01" },
  { sku: "GK30-BLK-44", name: "Asics Gel-Kayano 30", size: 44, stock: 5, res: 1, wh: "WH-AMS-02" },
];

const LIVE_CASES_KEY = "swapdesk.liveCases.v1";

const OUTCOME_VIEW: Record<Outcome, { status: TicketStatus; statusLabel: string }> = {
  arranged: { status: "resolved", statusLabel: "Resolved Autonomously" },
  clarification: { status: "processing", statusLabel: "Clarification Required" },
  denial: { status: "escalated", statusLabel: "Policy Denied" },
  escalation: { status: "escalated", statusLabel: "Escalated to Human" },
};

function actionsFromAttempts(attempts: Record<string, number>): string[] {
  const actions = Object.entries(attempts)
    .filter(([, count]) => count > 0)
    .map(([step]) => step.toUpperCase());
  return actions.length > 0 ? actions : ["VERIFY_STATE"];
}

function ticketFromResult(result: {
  case_id: string;
  run_id?: string | null;
  outcome: Outcome;
  reply: string;
  exchange_id: string | null;
  message: string;
  sku: string;
  attempts?: Record<string, number>;
}): Ticket {
  const view = OUTCOME_VIEW[result.outcome];
  return {
    id: result.case_id,
    message: result.message,
    status: view.status,
    statusLabel: view.statusLabel,
    actions: actionsFromAttempts(result.attempts ?? {}),
    time: "Just now",
    sku: result.sku,
    outcome: result.outcome,
    reply: result.reply,
    exchangeId: result.exchange_id,
    runId: result.run_id ?? undefined,
    live: true,
  };
}

function readLiveCases(): Ticket[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(LIVE_CASES_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as Ticket[]) : [];
  } catch {
    return [];
  }
}

function writeLiveCases(tickets: Ticket[]) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(
      LIVE_CASES_KEY,
      JSON.stringify(tickets.filter((ticket) => ticket.live)),
    );
  } catch {
    /* storage unavailable — non-fatal */
  }
}

type SwapDeskContextValue = {
  tickets: Ticket[];
  inventory: InventoryItem[];
  fixtures: FixturesOut | null;
  health: ApiHealth;
  apiError: string | null;
  refreshHealth: () => Promise<boolean>;
  loadFixtures: () => Promise<FixturesOut | null>;
  submitTicket: (input: TicketIn) => Promise<Ticket>;
  submitAgentTicket: (input: AgentTicketIn) => Promise<Ticket>;
  getCase: (id: string) => Promise<CaseStatusOut | null>;
  getTimeline: (id: string) => Promise<TimelineEvent[]>;
  continueCase: (id: string, input: ContinueIn) => Promise<ContinueOut>;
  armFault: (input: FaultIn) => Promise<FaultOut>;
  clearFaults: () => Promise<void>;
  /* Local demo helpers (offline fallback). */
  simulateTicket: () => Ticket;
  submitCustomerTicket: (message: string) => Ticket;
  resetMockData: () => void;
  getTicket: (id: string) => Ticket | undefined;
};

const SwapDeskContext = createContext<SwapDeskContextValue | null>(null);

export function SwapDeskProvider({ children }: { children: ReactNode }) {
  const [tickets, setTickets] = useState<Ticket[]>(createInitialTickets);
  const [inventory, setInventory] = useState<InventoryItem[]>(createInitialInventory);
  const [fixtures, setFixtures] = useState<FixturesOut | null>(null);
  const [health, setHealth] = useState<ApiHealth>("unknown");
  const [apiError, setApiError] = useState<string | null>(null);
  const seq = useRef(9045);

  /* Rehydrate cases created through the API after mount (avoids SSR drift). */
  useEffect(() => {
    const live = readLiveCases();
    if (live.length > 0) {
      setTickets((prev) => [...live, ...prev.filter((ticket) => !ticket.live)]);
    }
  }, []);

  useEffect(() => {
    writeLiveCases(tickets);
  }, [tickets]);

  const rememberTicket = useCallback((ticket: Ticket) => {
    setTickets((prev) => [ticket, ...prev.filter((existing) => existing.id !== ticket.id)]);
  }, []);

  const refreshHealth = useCallback(async () => {
    try {
      const result = await apiGetHealth();
      const online = result.ok === true;
      setHealth(online ? "online" : "offline");
      if (online) setApiError(null);
      return online;
    } catch (error) {
      setHealth("offline");
      setApiError(error instanceof Error ? error.message : "Health check failed");
      return false;
    }
  }, []);

  const loadFixtures = useCallback(async () => {
    try {
      const result = await apiGetFixtures();
      setFixtures(result);
      setApiError(null);
      return result;
    } catch (error) {
      setApiError(error instanceof Error ? error.message : "Could not load fixtures");
      return null;
    }
  }, []);

  const submitTicket = useCallback(
    async (input: TicketIn) => {
      const result = await apiSubmitTicket(input);
      const ticket = ticketFromResult({
        ...result,
        message: input.message || `Exchange ${input.order_item_id} to size ${input.size || "—"}`,
        sku: input.order_item_id,
        attempts: result.attempts,
      });
      rememberTicket(ticket);
      setHealth("online");
      setApiError(null);
      return ticket;
    },
    [rememberTicket],
  );

  const submitAgentTicket = useCallback(
    async (input: AgentTicketIn) => {
      const result = await apiSubmitAgentTicket(input);
      const ticket = ticketFromResult({
        case_id: result.case_id,
        run_id: result.run_id,
        outcome: result.outcome,
        reply: result.reply,
        exchange_id: result.exchange_id,
        message: input.message,
        sku: input.order_item_id ?? "—",
      });
      rememberTicket(ticket);
      setHealth("online");
      setApiError(null);
      return ticket;
    },
    [rememberTicket],
  );

  const getCase = useCallback(async (id: string) => {
    try {
      const status = await apiGetCase(id);
      const view = OUTCOME_VIEW[status.outcome];
      setTickets((prev) =>
        prev.map((ticket) =>
          ticket.id === id
            ? { ...ticket, status: view.status, statusLabel: view.statusLabel, outcomes: undefined } as Ticket
            : ticket,
        ),
      );
      return status;
    } catch {
      return null;
    }
  }, []);

  const getTimeline = useCallback(async (id: string) => {
    try {
      return await getCaseTimeline(id);
    } catch {
      return [];
    }
  }, []);

  const continueCase = useCallback(
    async (id: string, input: ContinueIn) => {
      const result = await apiContinueCase(id, input);
      const view = OUTCOME_VIEW[result.outcome];
      setTickets((prev) =>
        prev.map((ticket) =>
          ticket.id === id
            ? { ...ticket, status: view.status, statusLabel: view.statusLabel, reply: result.reply, exchangeId: result.exchange_id }
            : ticket,
        ),
      );
      return result;
    },
    [],
  );

  const armFault = useCallback(async (input: FaultIn) => {
    const result = await apiArmFault(input);
    setApiError(null);
    return result;
  }, []);

  const clearFaults = useCallback(async () => {
    try {
      await apiClearFaults();
      setApiError(null);
    } catch (error) {
      setApiError(error instanceof Error ? error.message : "Could not clear faults");
    }
  }, []);

  const simulateTicket = useCallback(() => {
    const ticket: Ticket = { id: `TCK-${seq.current++}`, ...MOCK_TICKET };
    setTickets((prev) => [ticket, ...prev]);
    setInventory((prev) =>
      prev.map((item) =>
        item.sku === MOCK_TICKET.sku
          ? { ...item, stock: Math.max(0, item.stock - 1), res: item.res + 1 }
          : item,
      ),
    );
    return ticket;
  }, []);

  const submitCustomerTicket = useCallback((message: string) => {
    const text = message.trim() || "My Jordan 4s arrived but are too tight. I need to exchange for a size 43.";
    const ticket: Ticket = {
      id: `TCK-${seq.current++}`,
      message: text,
      status: "processing",
      statusLabel: "Agent Processing",
      actions: ["INTAKE", "ROUTING"],
      time: "Just now",
      sku: "AJ4-MIL-43",
    };
    setTickets((prev) => [ticket, ...prev]);
    return ticket;
  }, []);

  const resetMockData = useCallback(() => {
    setTickets(createInitialTickets());
    setInventory(createInitialInventory());
    setApiError(null);
  }, []);

  const getTicket = useCallback((id: string) => tickets.find((ticket) => ticket.id === id), [tickets]);

  const value = useMemo(
    () => ({
      tickets,
      inventory,
      fixtures,
      health,
      apiError,
      refreshHealth,
      loadFixtures,
      submitTicket,
      submitAgentTicket,
      getCase,
      getTimeline,
      continueCase,
      armFault,
      clearFaults,
      simulateTicket,
      submitCustomerTicket,
      resetMockData,
      getTicket,
    }),
    [
      tickets,
      inventory,
      fixtures,
      health,
      apiError,
      refreshHealth,
      loadFixtures,
      submitTicket,
      submitAgentTicket,
      getCase,
      getTimeline,
      continueCase,
      armFault,
      clearFaults,
      simulateTicket,
      submitCustomerTicket,
      resetMockData,
      getTicket,
    ],
  );

  return <SwapDeskContext.Provider value={value}>{children}</SwapDeskContext.Provider>;
}

export function useSwapDesk() {
  const context = useContext(SwapDeskContext);
  if (!context) {
    throw new Error("useSwapDesk must be used within a SwapDeskProvider");
  }
  return context;
}

