"use client";

import { useMemo, useState, type FormEvent } from "react";
import Link from "next/link";
import { ArrowRight, CheckCircle2, Loader2, Send, ShieldAlert } from "lucide-react";
import { useSwapDesk } from "@/store/swapdesk";
import { ApiError, type Outcome } from "@/lib/api";

const DEFAULT_COMPLAINT = "My Jordan 4s arrived but are too tight. I need to exchange for a size 43.";

const OUTCOME_LABEL: Record<Outcome, string> = {
  arranged: "Exchange arranged",
  clarification: "Clarification required",
  denial: "Policy denial",
  escalation: "Escalated to human",
};

export function CustomerSimulationWidget() {
  const { fixtures, submitTicket, submitAgentTicket } = useSwapDesk();
  const [complaint, setComplaint] = useState("");
  const [mode, setMode] = useState<"deterministic" | "agent">("deterministic");
  const [rawOrderId, setRawOrderId] = useState("");
  const [rawItemId, setRawItemId] = useState("");
  const [rawSize, setRawSize] = useState("");
  const [sizeTouched, setSizeTouched] = useState(false);
  const [status, setStatus] = useState<"idle" | "routing" | "done">("idle");
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<{ caseId: string; outcome: Outcome; reply: string } | null>(null);

  const orders = useMemo(() => fixtures?.orders ?? [], [fixtures]);
  const selectedOrder = useMemo(() => orders.find((order) => order.id === rawOrderId), [orders, rawOrderId]);
  const items = useMemo(() => selectedOrder?.items ?? [], [selectedOrder]);
  const orderId = selectedOrder?.id ?? "";
  const itemId = items.some((item) => item.id === rawItemId) ? rawItemId : (items[0]?.id ?? "");
  const selectedItem = items.find((item) => item.id === itemId);
  const size = sizeTouched ? rawSize : (selectedItem?.size ?? "");
  const ready = orderId !== "" && itemId !== "";

  const handleOrderChange = (value: string) => {
    setRawOrderId(value);
    setRawItemId("");
    setSizeTouched(false);
  };

  const handleItemChange = (value: string) => {
    setRawItemId(value);
    setSizeTouched(false);
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (status === "routing") return;

    setStatus("routing");
    setError(null);
    setResult(null);
    try {
      if (mode === "agent") {
        const ticket = await submitAgentTicket({
          message: complaint.trim() || DEFAULT_COMPLAINT,
          order_id: orderId || null,
          order_item_id: itemId || null,
          size: size || null,
        });
        setResult({ caseId: ticket.id, outcome: ticket.outcome!, reply: ticket.reply ?? "" });
      } else {
        if (!ready) {
          throw new Error("Select an order and item for a deterministic run.");
        }
        const ticket = await submitTicket({ order_id: orderId, order_item_id: itemId, size, message: complaint.trim() });
        setResult({ caseId: ticket.id, outcome: ticket.outcome!, reply: ticket.reply ?? "" });
      }
      setStatus("done");
    } catch (caught) {
      const message =
        caught instanceof ApiError || caught instanceof Error
          ? caught.message
          : "The request failed. Is the backend running?";
      setError(message);
      setStatus("idle");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="panel space-y-5 p-5 sm:p-6">
      <div className="grid gap-2">
        <span className="block text-sm font-semibold">Handling mode</span>
        <div className="inline-flex rounded-lg border border-hairline bg-background/60 p-0.5 text-xs">
          {(["deterministic", "agent"] as const).map((option) => (
            <button
              key={option}
              type="button"
              onClick={() => setMode(option)}
              disabled={status === "routing"}
              className={`rounded-md px-3 py-1.5 font-medium transition-colors disabled:opacity-60 ${
                mode === option ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {option === "deterministic" ? "Deterministic (POST /v1/tickets)" : "Agent (POST /v1/agent/tickets)"}
            </button>
          ))}
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Order
          <select
            value={orderId}
            onChange={(event) => handleOrderChange(event.target.value)}
            disabled={status === "routing" || mode === "agent"}
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40 disabled:opacity-60"
          >
            <option value="">Select order…</option>
            {orders.map((order) => (
              <option key={order.id} value={order.id}>
                {order.id} · {order.customer_ref}
              </option>
            ))}
          </select>
        </label>

        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Item
          <select
            value={itemId}
            onChange={(event) => handleItemChange(event.target.value)}
            disabled={status === "routing" || mode === "agent" || items.length === 0}
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40 disabled:opacity-60"
          >
            <option value="">Select item…</option>
            {items.map((item) => (
              <option key={item.id} value={item.id}>
                {item.id} · {item.sku} · {item.size}
              </option>
            ))}
          </select>
        </label>

        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Requested size
          <input
            value={size}
            onChange={(event) => {
              setRawSize(event.target.value);
              setSizeTouched(true);
            }}
            disabled={status === "routing"}
            placeholder="43"
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40 disabled:opacity-60"
          />
        </label>
      </div>

      <div className="space-y-2">
        <label htmlFor="complaint" className="block text-sm font-semibold">
          Customer complaint
        </label>
        <textarea
          id="complaint"
          name="complaint"
          rows={5}
          value={complaint}
          onChange={(event) => setComplaint(event.target.value)}
          placeholder={DEFAULT_COMPLAINT}
          disabled={status === "routing"}
          className="w-full resize-none rounded-xl border border-hairline bg-background/60 p-4 text-sm leading-relaxed text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40 disabled:opacity-60"
        />
      </div>

      <button
        type="submit"
        disabled={status === "routing"}
        className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-70 sm:w-auto"
      >
        {status === "routing" ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            {mode === "agent" ? "Routing to agent…" : "Running exchange…"}
          </>
        ) : (
          <>
            <Send className="h-4 w-4" />
            Submit to SwapDesk
          </>
        )}
      </button>

      {error && (
        <div className="rise flex items-start gap-3 rounded-xl border border-danger/25 bg-danger/[0.06] p-4">
          <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0 text-danger" />
          <p className="text-sm text-danger">{error}</p>
        </div>
      )}

      {status === "done" && result && (
        <div className="rise flex flex-col gap-3 rounded-xl border border-success/20 bg-success/[0.06] p-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-start gap-3">
            <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-success" />
            <div>
              <p className="text-sm font-semibold text-foreground">
                {result.caseId} · {OUTCOME_LABEL[result.outcome]}
              </p>
              <p className="text-xs text-muted-foreground">{result.reply}</p>
            </div>
          </div>
          <Link
            href={`/ticket/${result.caseId}`}
            className="inline-flex shrink-0 items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60"
          >
            View case
            <ArrowRight className="h-3.5 w-3.5" />
          </Link>
        </div>
      )}
    </form>
  );
}

