"use client";

import { useMemo, useState, type FormEvent } from "react";
import Link from "next/link";
import { ArrowRight, CheckCircle2, Clock, Loader2, Send, ShieldAlert } from "lucide-react";
import { useSwapDesk, type Ticket } from "@/store/swapdesk";
import { ApiError, type ExecutionStatus } from "@/lib/api";

const DEFAULT_COMPLAINT = "My Jordan 4s arrived but are too tight. I need to exchange for a size 43.";

const EXECUTION_LABEL: Record<ExecutionStatus, string> = {
  queued: "Accepted · queued for the worker",
  running: "Agent is working…",
  waiting_input: "Waiting for your reply",
  completed: "Run complete",
  failed: "Run failed — needs attention",
};

function LiveTicketResult({ ticket }: { ticket: Ticket }) {
  const active = ticket.executionStatus === "queued" || ticket.executionStatus === "running";
  return (
    <div className="rise flex flex-col gap-3 rounded-xl border border-success/20 bg-success/[0.06] p-4 sm:flex-row sm:items-center sm:justify-between">
      <div className="flex items-start gap-3">
        {active ? (
          <Clock className="mt-0.5 h-4 w-4 shrink-0 text-success" />
        ) : (
          <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-success" />
        )}
        <div className="space-y-0.5">
          <p className="text-sm font-semibold text-foreground">
            {ticket.id} · {ticket.statusLabel}
          </p>
          <p className="text-xs text-muted-foreground">
            {ticket.executionStatus ? EXECUTION_LABEL[ticket.executionStatus] : "Accepted (202)"}
            {ticket.duplicate ? " · existing case (idempotent)" : ""}
          </p>
          {ticket.reply && <p className="text-xs text-muted-foreground">{ticket.reply}</p>}
          {active && (
            <p className="text-[11px] text-muted-foreground/80">
              Progress is polled from GET /v1/agent/cases/{ticket.id}. Start the worker
              (<span className="font-mono">python -m swapdesk.worker</span>) to advance the queue.
            </p>
          )}
        </div>
      </div>
      <Link
        href={`/ticket/${ticket.id}`}
        className="inline-flex shrink-0 items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-xs font-medium text-foreground transition-colors hover:bg-accent/60"
      >
        View case
        <ArrowRight className="h-3.5 w-3.5" />
      </Link>
    </div>
  );
}

export function CustomerSimulationWidget() {
  const { fixtures, submitAgentTicket, getTicket } = useSwapDesk();
  const [complaint, setComplaint] = useState("");
  const [rawOrderId, setRawOrderId] = useState("");
  const [rawItemId, setRawItemId] = useState("");
  const [rawSize, setRawSize] = useState("");
  const [sizeTouched, setSizeTouched] = useState(false);
  const [status, setStatus] = useState<"idle" | "routing" | "done">("idle");
  const [error, setError] = useState<string | null>(null);
  const [caseId, setCaseId] = useState<string | null>(null);

  const orders = useMemo(() => fixtures?.orders ?? [], [fixtures]);
  const selectedOrder = useMemo(() => orders.find((order) => order.id === rawOrderId), [orders, rawOrderId]);
  const items = useMemo(() => selectedOrder?.items ?? [], [selectedOrder]);
  const orderId = selectedOrder?.id ?? "";
  const itemId = items.some((item) => item.id === rawItemId) ? rawItemId : (items[0]?.id ?? "");
  const selectedItem = items.find((item) => item.id === itemId);
  const size = sizeTouched ? rawSize : (selectedItem?.size ?? "");
  const liveTicket = caseId ? getTicket(caseId) : undefined;

  const handleOrderChange = (value: string) => {
    setRawOrderId(value);
    setRawItemId("");
    setSizeTouched(false);
  };

  const handleItemChange = (value: string) => {
    setRawItemId(value);
    setSizeTouched(false);
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (status === "routing") return;

    setStatus("routing");
    setError(null);
    setCaseId(null);
    try {
      const ticket = await submitAgentTicket({
        message: complaint.trim() || DEFAULT_COMPLAINT,
        order_id: orderId || null,
        order_item_id: itemId || null,
        size: size || null,
      });
      setCaseId(ticket.id);
      setStatus("done");
    } catch (caught) {
      const message =
        caught instanceof ApiError || caught instanceof Error
          ? caught.message
          : "The request failed. Is the backend running?";
      setError(message);
      setStatus("idle");
    }
  };

  return (
    <form onSubmit={handleSubmit} className="panel space-y-5 p-5 sm:p-6">
      <div className="rounded-lg border border-hairline bg-background/40 p-3 text-xs text-muted-foreground">
        Submits to <span className="font-mono text-foreground">POST /v1/agent/tickets</span> →{" "}
        <span className="font-semibold text-foreground">202 Accepted</span>. The run is queued and
        polled via <span className="font-mono text-foreground">GET /v1/agent/cases/&#123;id&#125;</span>.
      </div>

      <div className="grid gap-3 sm:grid-cols-3">
        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Order (optional)
          <select
            value={orderId}
            onChange={(event) => handleOrderChange(event.target.value)}
            disabled={status === "routing"}
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40 disabled:opacity-60"
          >
            <option value="">Let the agent look it up…</option>
            {orders.map((order) => (
              <option key={order.id} value={order.id}>
                {order.id} · {order.customer_ref}
              </option>
            ))}
          </select>
        </label>

        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Item (optional)
          <select
            value={itemId}
            onChange={(event) => handleItemChange(event.target.value)}
            disabled={status === "routing" || items.length === 0}
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-success/40 disabled:opacity-60"
          >
            <option value="">Select item…</option>
            {items.map((item) => (
              <option key={item.id} value={item.id}>
                {item.id} · {item.sku} · {item.size}
              </option>
            ))}
          </select>
        </label>

        <label className="grid gap-1.5 text-xs font-medium text-muted-foreground">
          Requested size (optional)
          <input
            value={size}
            onChange={(event) => {
              setRawSize(event.target.value);
              setSizeTouched(true);
            }}
            disabled={status === "routing"}
            placeholder="43"
            className="rounded-lg border border-hairline bg-background/60 px-3 py-2 text-sm text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40 disabled:opacity-60"
          />
        </label>
      </div>

      <div className="space-y-2">
        <label htmlFor="complaint" className="block text-sm font-semibold">
          Customer complaint
        </label>
        <textarea
          id="complaint"
          name="complaint"
          rows={5}
          value={complaint}
          onChange={(event) => setComplaint(event.target.value)}
          placeholder={DEFAULT_COMPLAINT}
          disabled={status === "routing"}
          className="w-full resize-none rounded-xl border border-hairline bg-background/60 p-4 text-sm leading-relaxed text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-success/40 disabled:opacity-60"
        />
      </div>

      <button
        type="submit"
        disabled={status === "routing"}
        className="inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-70 sm:w-auto"
      >
        {status === "routing" ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            Submitting…
          </>
        ) : (
          <>
            <Send className="h-4 w-4" />
            Submit to SwapDesk
          </>
        )}
      </button>

      {error && (
        <div className="rise flex items-start gap-3 rounded-xl border border-danger/25 bg-danger/[0.06] p-4">
          <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0 text-danger" />
          <p className="text-sm text-danger">{error}</p>
        </div>
      )}

      {status === "done" && liveTicket && <LiveTicketResult ticket={liveTicket} />}
    </form>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import {
  ArrowLeft,
  Clock3,
  Loader2,
  RefreshCw,
  Send,
  ShieldAlert,
  ShieldCheck,
  TriangleAlert,
} from "lucide-react";
import { AppShell } from "@/components/AppShell";
import { useSwapDesk, isActiveExecution } from "@/store/swapdesk";
import { ApiError, type ExecutionStatus, type Outcome, type TimelineEvent } from "@/lib/api";

const OUTCOME_META: Record<Outcome, { label: string; tone: "success" | "warning" | "danger" | "primary" }> = {
  arranged: { label: "Exchange arranged", tone: "success" },
  clarification: { label: "Clarification required", tone: "primary" },
  denial: { label: "Policy denial", tone: "warning" },
  escalation: { label: "Escalated to human", tone: "danger" },
};

const EXECUTION_META: Record<ExecutionStatus, { label: string; tone: "success" | "warning" | "danger" | "primary" }> = {
  queued: { label: "Queued", tone: "primary" },
  running: { label: "Running", tone: "primary" },
  waiting_input: { label: "Waiting for input", tone: "warning" },
  completed: { label: "Completed", tone: "success" },
  failed: { label: "Failed", tone: "danger" },
};

function humanize(value: string | null): string {
  if (!value) return "Event";
  return value.replace(/_/g, " ").replace(/\b\w/g, (char) => char.toUpperCase());
}

function eventDetail(event: TimelineEvent): string {
  const parts = [event.event.replace(/_/g, " ")];
  if (event.run_id) parts.push(`run=${event.run_id}`);
  if (event.status) parts.push(`status=${event.status}`);
  const result = event.result ?? {};
  for (const key of ["exchange_id", "return_id", "label_id", "tracking_ref"]) {
    const value = result[key];
    if (typeof value === "string") parts.push(`${key}=${value}`);
  }
  if (result.duplicate === true) parts.push("duplicate reused");
  return parts.join(" · ");
}

function toneClass(tone: "success" | "warning" | "danger" | "primary"): string {
  switch (tone) {
    case "success":
      return "border-success/15 bg-success/[0.07] text-success";
    case "warning":
      return "border-warning/15 bg-warning/[0.07] text-warning";
    case "danger":
      return "border-danger/15 bg-danger/[0.07] text-danger";
    default:
      return "border-primary/15 bg-primary/[0.07] text-primary";
  }
}

export default function TicketDetailPage() {
  const params = useParams<{ id: string }>();
  const id = params?.id;
  const { getTicket, loadCase, getTimeline, continueCase, caseStatus } = useSwapDesk();
  const localTicket = id ? getTicket(id) : undefined;
  const status = id ? caseStatus[id] : undefined;

  const [events, setEvents] = useState<TimelineEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [consentSize, setConsentSize] = useState("");
  const [reply, setReply] = useState("");
  const [continuing, setContinuing] = useState(false);
  const [continueError, setContinueError] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    setLoadError(null);
    const [nextStatus, nextEvents] = await Promise.all([loadCase(id), getTimeline(id)]);
    setEvents(nextEvents);
    if (!nextStatus) {
      setLoadError("No backend case with this id. It may be a local demo ticket.");
    }
    setLoading(false);
  }, [id, loadCase, getTimeline]);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      void load();
    }, 0);
    return () => window.clearTimeout(timer);
  }, [load]);

  /* Refresh the timeline as queued runs advance. */
  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    void getTimeline(id).then((next) => {
      if (!cancelled) setEvents(next);
    });
    return () => {
      cancelled = true;
    };
  }, [id, getTimeline, status?.current_run_id, status?.execution_status]);

  const active = isActiveExecution(status?.execution_status);
  useEffect(() => {
    if (!id || !active) return;
    const timer = window.setInterval(() => {
      void getTimeline(id).then(setEvents);
    }, 1500);
    return () => window.clearInterval(timer);
  }, [id, active, getTimeline]);

  const handleContinue = async () => {
    if (!id || continuing) return;
    if (!reply.trim() && !consentSize.trim()) {
      setContinueError("Add a reply or a consent size before continuing.");
      return;
    }
    setContinuing(true);
    setContinueError(null);
    try {
      await continueCase(id, {
        message: reply.trim(),
        consent_size: consentSize || null,
      });
      setReply("");
      setConsentSize("");
    } catch (caught) {
      setContinueError(caught instanceof ApiError || caught instanceof Error ? caught.message : "Continue failed");
    } finally {
      setContinuing(false);
    }
  };

  const outcome = status?.outcome ?? undefined;
  const outcomeMeta = outcome ? OUTCOME_META[outcome] : null;
  const executionMeta = status ? EXECUTION_META[status.execution_status] : null;
  const canContinue = status?.execution_status === "waiting_input" || status?.execution_status === "failed";

  return (
    <AppShell crumbs={[{ label: "SwapDesk", to: "/" }, { label: "Mission Control", to: "/" }, { label: id ?? "Unknown" }]}>
      <div className="mx-auto w-full max-w-6xl space-y-6">
        <header className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <h1 className="text-2xl font-semibold">
              {status?.reply ?? localTicket?.message ?? "Case not found"}
            </h1>
            <p className="mt-1 text-sm text-muted-foreground">
              {id} {outcomeMeta ? `· ${outcomeMeta.label}` : status ? `· ${executionMeta?.label ?? ""}` : "· no matching case"}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => void load()}
              disabled={loading}
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-sm text-foreground transition-colors hover:bg-accent/60 disabled:opacity-60"
            >
              <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} /> Refresh
            </button>
            <Link
              href="/"
              className="inline-flex items-center gap-2 rounded-lg border border-hairline bg-card/60 px-3 py-2 text-sm text-foreground transition-colors hover:bg-accent/60"
            >
              <ArrowLeft className="h-4 w-4" /> Back
            </Link>
          </div>
        </header>

        <section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <div className="panel flex items-center gap-3 p-4">
            <span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl border ${executionMeta ? toneClass(executionMeta.tone) : "border-hairline text-muted-foreground"}`}>
              {active ? <Loader2 className="h-4 w-4 animate-spin" /> : status?.execution_status === "failed" ? <TriangleAlert className="h-4 w-4" /> : <Clock3 className="h-4 w-4" />}
            </span>
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Execution</p>
              <p className="truncate text-sm font-semibold">{executionMeta?.label ?? localTicket?.statusLabel ?? "Unknown"}</p>
            </div>
          </div>
          <div className="panel flex items-center gap-3 p-4">
            <span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl border ${outcomeMeta ? toneClass(outcomeMeta.tone) : "border-hairline text-muted-foreground"}`}>
              {outcomeMeta?.tone === "success" ? <ShieldCheck className="h-4 w-4" /> : outcomeMeta ? <ShieldAlert className="h-4 w-4" /> : <Clock3 className="h-4 w-4" />}
            </span>
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Outcome</p>
              <p className="truncate text-sm font-semibold">{outcomeMeta?.label ?? "Pending"}</p>
            </div>
          </div>
          <div className="panel flex items-center gap-3 p-4">
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Exchange</p>
              <p className="truncate font-mono text-sm">{status?.exchange_id ?? localTicket?.exchangeId ?? "—"}</p>
            </div>
          </div>
          <div className="panel flex items-center gap-3 p-4">
            <div className="min-w-0">
              <p className="text-xs text-muted-foreground">Runs</p>
              <p className="truncate font-mono text-sm">{status?.runs?.join(", ") || localTicket?.runId || "—"}</p>
            </div>
          </div>
        </section>

        {(status?.clarification || status?.error) && (
          <section className="panel space-y-2 p-5">
            {status?.clarification && (
              <div>
                <p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">Clarification needed</p>
                <p className="mt-1 text-sm text-foreground">{status.clarification}</p>
              </div>
            )}
            {status?.error && (
