export function isActiveExecution(status?: ExecutionStatus): boolean {
  return status === "queued" || status === "running";
}

function relativeTime(iso: string): string {
  const elapsed = Date.now() - Date.parse(iso);
  if (Number.isNaN(elapsed) || elapsed < 0) return "Just now";
  const minutes = Math.floor(elapsed / 60_000);
  if (minutes < 1) return "Just now";
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}

/** Map a `GET /v1/agent/cases` row onto the UI ticket shape. */
function ticketFromCase(item: AgentCaseListItem): Ticket {
  const view = statusView(item);
  return {
    id: item.case_id,
    message: item.message,
    status: view.status,
    statusLabel: view.statusLabel,
    actions: view.actions,
    time: relativeTime(item.updated_at),
    sku: item.order_item_id ?? item.size ?? "—",
    outcome: item.outcome ?? undefined,
    reply: item.reply ?? undefined,
    runId: item.current_run_id ?? undefined,
    live: true,
